  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly or implicitly takes personal responsibility for securing a benefit, resource, recognition, or policy outcome for their constituents, state, or a specific group. This includes announcing funding, legislation, or initiatives where the senator highlights their direct role in achieving the result.",
    "clarification": "Credit-claiming is identified when a senator uses language such as 'I secured,' 'I helped obtain,' 'I authored,' 'I fought for,' or similar phrasing that directly links their actions to a tangible or intangible benefit. It can also include taking credit for advocacy that led to a positive outcome, even if the senator was part of a larger effort. The focus is on the senator's explicit or strongly implied role in the achievement.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states he authored legislation that created the National Center designation for Bismarck State College and takes direct credit for securing this recognition and funding. This is a clear example of credit-claiming, as he links his legislative action to a specific outcome."
      },
      {
        "document_id": "3482",
        "explanation": "Sens. Mikulski and Cardin announce federal funding for firefighters, with Sen. Mikulski explicitly stating her role on the Appropriations Subcommittee that funds the program and her ongoing efforts to increase its funding. This directly ties her actions to the secured benefit."
      },
      {
        "document_id": "4585",
        "explanation": "Senator Schumer announces federal fire grants for Westchester County and explicitly states he pushed for additional funding for the Assistance to Firefighters Grant Program. He takes credit for ensuring local departments receive necessary resources."
      }
    ],
    "negative_clarification": "Not credit-claiming when a senator discusses policy, critiques others, or expresses support for an issue without explicitly or implicitly linking their personal actions to a specific benefit or outcome. Statements of general advocacy, policy positions, or critiques of others do not qualify as credit-claiming unless the senator directly ties their efforts to a tangible result.",
    "negative_examples": [
      {
        "document_id": "57",
        "explanation": "Senator Kennedy introduces legislation on stem cell research but does not claim personal credit for its passage or implementation. The focus is on advocating for the bill, not taking credit for a secured outcome."
      },
